<?php
declare(strict_types=1);
namespace KraPin;
final class KraService {
 private string $env;private bool $mock;private string $base;
 public function __construct(string $env,bool $mock){$this->env=$env;$this->mock=$mock;$this->base=$env==='production'?'https://api.kra.go.ke':'https://sbx.kra.go.ke';}
 private function request(string $url,array $headers=[],?array $payload=null):array{$ch=curl_init($url);$h=$headers;if($payload!==null)$h[]='Content-Type: application/json';curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_HTTPHEADER=>$h,CURLOPT_POST=>$payload!==null,CURLOPT_POSTFIELDS=>$payload===null?null:json_encode($payload,JSON_THROW_ON_ERROR)]);$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);if($raw===false){curl_close($ch);throw new \RuntimeException('Upstream unavailable');}curl_close($ch);$data=json_decode($raw,true);if(!is_array($data))throw new \RuntimeException('Unexpected upstream response');return [$status,$data];}
 private function token(string $key,string $secret):string{static $cache=[];if(isset($cache[$key])&&$cache[$key]['expires']>time()+60)return $cache[$key]['value'];[$status,$d]=$this->request($this->base.'/v1/token/generate?grant_type=client_credentials',['Authorization'=>'Basic '.base64_encode($key.':'.$secret)]);if($status>=400||empty($d['access_token']))throw new \RuntimeException('KRA token request failed');$cache[$key]=['value'=>$d['access_token'],'expires'=>time()+(int)($d['expires_in']??3600)];return $cache[$key]['value'];}
 public function verify(bool $byId,string $value,string $type):array{if($this->mock){$found=$byId?$value==='00000000':$value==='A000000000B';return ['found'=>$found,'pin'=>$found?'A000000000B':null,'taxpayer_name'=>$found?'DEMO T*****':null,'environment'=>$this->env,'mock'=>true,'raw'=>null];}
 $key=getenv($byId?'KRA_PIN_BY_ID_CONSUMER_KEY':'KRA_PIN_CONSUMER_KEY')?:getenv('KRA_PIN_CONSUMER_KEY');$secret=getenv($byId?'KRA_PIN_BY_ID_CONSUMER_SECRET':'KRA_PIN_CONSUMER_SECRET')?:getenv('KRA_PIN_CONSUMER_SECRET');$t=$this->token((string)$key,(string)$secret);$path=$byId?'/checker/v1/pin':'/checker/v1/pinbypin';$payload=$byId?['TaxpayerType'=>$type,'TaxpayerID'=>$value]:['KRAPIN'=>$value];[$status,$d]=$this->request($this->base.$path,['Authorization'=>'Bearer '.$t],$payload);if($status===404||($status>=400&&(string)($d['errorCode']??'')==='30002'))return ['found'=>false,'pin'=>null,'taxpayer_name'=>null,'environment'=>$this->env,'mock'=>false,'raw'=>null];$record=$d['PINDATA']??$d;$pin=$record['KRAPIN']??null;$name=$record['Name']??null;if($status>=400||(!$pin&&!$name))throw new \RuntimeException('Unexpected KRA response shape');return ['found'=>true,'pin'=>$pin,'taxpayer_name'=>$name,'environment'=>$this->env,'mock'=>false,'raw'=>null];}
}
